const canvas=document.getElementById('game'),ctx=canvas.getContext('2d');
let W,H,dpr,playing=false,last=0,time=0,won=false;
const player={x:0,z:0,a:0,hp:100,stamina:100,kills:0,wood:0,cool:0,walk:0};
const monsters=[],trees=[],rocks=[],leaves=[],particles=[];
const WORLD=1100;
function resize(){dpr=Math.min(devicePixelRatio||1,2);W=innerWidth;H=innerHeight;canvas.width=W*dpr;canvas.height=H*dpr;ctx.setTransform(dpr,0,0,dpr,0,0)}addEventListener('resize',resize);resize();
function rnd(seed){seed=(seed*9301+49297)%233280;return seed/233280}let seed=419;
function random(){seed=(seed*9301+49297)%233280;return seed/233280}
for(let i=0;i<420;i++){let x=(random()-.5)*WORLD*2,z=(random()-.5)*WORLD*2;if(Math.hypot(x,z)<35)continue;trees.push({x,z,s:18+random()*38,c:random(),type:random()>.92?'dead':'pine'})}
for(let i=0;i<70;i++)rocks.push({x:(random()-.5)*WORLD*2,z:(random()-.5)*WORLD*2,s:3+random()*8});
for(let i=0;i<160;i++)leaves.push({x:(random()-.5)*WORLD*2,z:(random()-.5)*WORLD*2,r:random()*6.28});
function spawnMonsters(){monsters.length=0;for(let i=0;i<12;i++){let a=random()*6.28,d=110+random()*550;monsters.push({x:Math.cos(a)*d,z:Math.sin(a)*d,hp:i>8?70:45,max:i>8?70:45,kind:i%3,hit:0,phase:random()*6.28,dead:false})}}
spawnMonsters();
const keys={};addEventListener('keydown',e=>keys[e.key.toLowerCase()]=true);addEventListener('keyup',e=>keys[e.key.toLowerCase()]=false);
canvas.addEventListener('mousemove',e=>{if(playing&&!matchMedia('(pointer:coarse)').matches)player.a+=(e.movementX||0)*.0022});
canvas.addEventListener('mousedown',()=>hit());
const stick=document.getElementById('stick'),knob=document.getElementById('stickKnob');let touchMove=null;
stick.addEventListener('touchstart',e=>{touchMove=e.changedTouches[0];updateStick(touchMove)}, {passive:false});stick.addEventListener('touchmove',e=>{e.preventEventDefault?.();touchMove=e.changedTouches[0];updateStick(touchMove)}, {passive:false});stick.addEventListener('touchend',()=>{touchMove=null;knob.style.transform=''});
function updateStick(t){let r=stick.getBoundingRect(),cx=r.left+r.width/2,cy=r.top+r.height/2,dx=t.clientX-cx,dy=t.clientY-cy,l=Math.hypot(dx,dy),m=34;if(l>m){dx=dx/l*m;dy=dy/l*m}knob.style.transform=`translate(${dx}px,${dy}px)`;stick.dx=dx/m;stick.dy=dy/m}
document.getElementById('hit').addEventListener('touchstart',e=>{e.preventDefault();hit()});
let lookTouch=null;canvas.addEventListener('touchstart',e=>{if(e.target===canvas&&e.touches.length){lookTouch=e.touches[0]}},{passive:false});canvas.addEventListener('touchmove',e=>{if(lookTouch){let t=e.touches[0];player.a+=(t.clientX-lookTouch.clientX)*.008;lookTouch=t;e.preventDefault()}},{passive:false});
function getRectEl(e){return e.target.getBoundingClientRect()} 
HTMLElement.prototype.getBoundingClientRect=function(){return this.getBoundingClientRect?undefined:undefined};
function hit(){if(!playing||player.cool>0)return;player.cool=.38;document.getElementById('crosshair').classList.add('crosshairHit');setTimeout(()=>document.getElementById('crosshair').classList.remove('crosshairHit'),100);let hits=0;for(const m of monsters){if(m.dead)continue;let dx=m.x-player.x,dz=m.z-player.z,d=Math.hypot(dx,dz),ang=Math.atan2(dz,dx)-player.a;while(ang>Math.PI)ang-=Math.PI*2;while(ang<-Math.PI)ang+=Math.PI*2;if(d<48&&Math.abs(ang)<.75){m.hp-=28;m.hit=.18;m.phase+=1;hits++;for(let i=0;i<8;i++)particles.push({x:m.x,z:m.z,y:15,vx:(random()-.5)*18,vz:(random()-.5)*18,vy:5+random()*12,life:.7,c:'#a47a3f'});if(m.hp<=0){m.dead=true;player.kills++;player.wood+=m.kind===2?3:1;toast(m.kind===2?'ENT RETUMBANTE DERROTADO':'Monstro abatido')}}}if(!hits){}updateHUD()}
function toast(t){let el=document.getElementById('toast');el.textContent=t;el.classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>el.classList.remove('show'),1500)}
function updateHUD(){document.getElementById('health').style.width=player.hp+'%';document.getElementById('stamina').style.width=player.stamina+'%';document.getElementById('kills').textContent=player.kills;document.getElementById('wood').textContent=player.wood;document.getElementById('questText').innerHTML=`Monstros derrotados <b>${Math.min(player.kills,12)} / 12</b>`;document.getElementById('level').textContent=`LV. ${1+Math.floor(player.kills/4)}`}
function worldToScreen(x,z){let dx=x-player.x,dz=z-player.z,c=Math.cos(-player.a),s=Math.sin(-player.a);let rx=dx*c-dz*s,rz=dx*s+dz*c;if(rz<2)return null;let f=H*.82;let sx=W/2+(rx/rz)*f,sy=H*.57-(H*.22/rz)*f;let scale=f/rz;return{x:sx,y:sy,scale,rz}}
function poly(points,fill,stroke){ctx.beginPath();points.forEach((p,i)=>i?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y));ctx.closePath();ctx.fillStyle=fill;ctx.fill();if(stroke){ctx.strokeStyle=stroke;ctx.stroke()}}
function drawGround(){let horizon=H*.57;let g=ctx.createLinearGradient(0,horizon,0,H);g.addColorStop(0,'#71805a');g.addColorStop(.25,'#4d6541');g.addColorStop(1,'#1a3020');ctx.fillStyle=g;ctx.fillRect(0,horizon,W,H-horizon);ctx.fillStyle='#8b9568';ctx.fillRect(0,0,W,horizon);let sun=ctx.createRadialGradient(W*.72,H*.25,20,W*.72,H*.25,H*.52);sun.addColorStop(0,'rgba(232,220,155,.55)');sun.addColorStop(1,'rgba(232,220,155,0)');ctx.fillStyle=sun;ctx.fillRect(0,0,W,horizon);ctx.fillStyle='#243929';ctx.beginPath();ctx.moveTo(0,horizon);for(let i=0;i<=W;i+=40){let h=22+((i*17)%55);ctx.lineTo(i,horizon-h)}ctx.lineTo(W,horizon);ctx.fill();ctx.fillStyle='#1a2c20';ctx.beginPath();ctx.moveTo(0,horizon-20);for(let i=0;i<=W;i+=55){ctx.lineTo(i,horizon-45-((i*31)%55)}ctx.lineTo(W,horizon);ctx.fill();}
function drawTree(t){let p=worldToScreen(t.x,t.z);if(!p)return;if(p.x<-150||p.x>W+150||p.rz>900)return;let s=p.scale*t.s/18;if(t.type==='dead'){ctx.strokeStyle='#3b3427';ctx.lineWidth=Math.max(2,s*.16);ctx.beginPath();ctx.moveTo(p.x,p.y);ctx.lineTo(p.x,p.y-s*2.4);ctx.stroke();ctx.lineWidth=Math.max(1,s*.08);ctx.beginPath();ctx.moveTo(p.x,p.y-s*1.7);ctx.lineTo(p.x-s*.8,p.y-s*2.5);ctx.moveTo(p.x,p.y-s*1.3);ctx.lineTo(p.x+s*.6,p.y-s*2.1);ctx.stroke();return}ctx.fillStyle='#4a3522';ctx.fillRect(p.x-s*.13,p.y-s*1.7,s*.26,s*1.7);ctx.fillStyle='#263d27';ctx.beginPath();ctx.moveTo(p.x,p.y-s*3.2);ctx.lineTo(p.x-s*.95,p.y-s*.75);ctx.lineTo(p.x+s*.95,p.y-s*.75);ctx.fill();ctx.fillStyle='#34492f';ctx.beginPath();ctx.moveTo(p.x,p.y-s*3.9);ctx.lineTo(p.x-s*.7,p.y-s*1.55);ctx.lineTo(p.x+s*.7,p.y-s*1.55);ctx.fill();}
function drawMonster(m){if(m.dead)return;let p=worldToScreen(m.x,m.z);if(!p||p.rz>850)return;let s=p.scale*(m.kind===2?1.8:.95);let bob=Math.sin(time*3+m.phase)*2*s;ctx.save();ctx.translate(p.x,p.y+bob);ctx.rotate(Math.sin(time*2+m.phase)*.03);if(m.hit>0)ctx.globalAlpha=.6+Math.sin(time*35)*.4;let wood=['#79613a','#8b7045','#4d3a27'][m.kind];ctx.fillStyle=wood;if(m.kind===0){ctx.fillRect(-s*.35,-s*2.1,s*.7,s*1.8);ctx.beginPath();ctx.arc(0,-s*2.35,s*.5,0,7);ctx.fill();ctx.fillStyle='#b3b07a';ctx.fillRect(-s*.18,-s*2.45,s*.08,s*.08);ctx.fillRect(s*.1,-s*2.45,s*.08,s*.08)}else if(m.kind===1){ctx.beginPath();ctx.moveTo(0,-s*3);ctx.lineTo(-s*.8,-s*.9);ctx.lineTo(s*.8,-s*.9);ctx.fill();ctx.fillStyle='#9a7d48';ctx.fillRect(-s*.25,-s*1.9,s*.5,s*1.4);ctx.fillStyle='#b9bd7e';ctx.beginPath();ctx.arc(-s*.12,-s*2.25,s*.06,0,7);ctx.arc(s*.12,-s*2.25,s*.06,0,7);ctx.fill()}else{ctx.fillStyle='#3f3925';ctx.beginPath();ctx.ellipse(0,-s*1.4,s*.75,s*1.5,0,0,7);ctx.fill();ctx.beginPath();ctx.arc(0,-s*2.55,s*.7,0,7);ctx.fill();ctx.fillStyle='#9aa16a';ctx.fillRect(-s*.35,-s*2.65,s*.12,s*.12);ctx.fillRect(s*.23,-s*2.65,s*.12,s*.12)}ctx.restore();if(p.rz<220){ctx.fillStyle='#21160f';ctx.fillRect(p.x-s*.55,p.y-s*3.25,s*1.1,3);ctx.fillStyle=m.hp/m.max>.4?'#8c9c58':'#aa543c';ctx.fillRect(p.x-s*.55,p.y-s*3.25,s*1.1*(m.hp/m.max),3)}}
function drawRock(r){let p=worldToScreen(r.x,r.z);if(!p||p.rz>700)return;let s=p.scale*r.s/8;ctx.fillStyle='#6f745f';ctx.beginPath();ctx.moveTo(p.x-s,p.y);ctx.lineTo(p.x-s*.7,p.y-s*.55);ctx.lineTo(p.x+s*.5,p.y-s*.7);ctx.lineTo(p.x+s,p.y);ctx.fill()}
function drawParticles(){for(let i=particles.length-1;i>=0;i--){let q=particles[i],p=worldToScreen(q.x,q.z);if(p){ctx.globalAlpha=Math.max(0,q.life);ctx.fillStyle=q.c;ctx.fillRect(p.x,p.y-q.y*p.scale/4,3*p.scale,3*p.scale)}q.life-=.016;q.vy-=.6;q.y+=q.vy*.016;q.x+=q.vx*.016;q.z+=q.vz*.016;if(q.life<=0)particles.splice(i,1)}ctx.globalAlpha=1}
function update(dt){if(!playing)return;time+=dt;player.cool=Math.max(0,player.cool-dt);for(const m of monsters)m.hit=Math.max(0,m.hit-dt);let forward=(keys.w?1:0)-(keys.s?1:0),strafe=(keys.d?1:0)-(keys.a?1:0);if(stick.dx||stick.dy){forward=-stick.dy||0;strafe=stick.dx||0}let len=Math.hypot(forward,strafe)||1;forward/=len;strafe/=len;let sx=Math.cos(player.a)*forward+Math.cos(player.a+Math.PI/2)*strafe,sz=Math.sin(player.a)*forward+Math.sin(player.a+Math.PI/2)*strafe;let running=keys.shift&&player.stamina>0,spd=running?78:48;if(running)player.stamina-=24*dt;else player.stamina=Math.min(100,player.stamina+15*dt);if(Math.abs(forward)+Math.abs(strafe)){player.x+=sx*spd*dt;player.z+=sz*spd*dt;player.walk+=dt*(running?12:8)}player.x=Math.max(-WORLD,Math.min(WORLD,player.x));player.z=Math.max(-WORLD,Math.min(WORLD,player.z));for(const m of monsters){if(m.dead)continue;let dx=player.x-m.x,dz=player.z-m.z,d=Math.hypot(dx,dz);if(d<520&&d>0){let speed=(m.kind===2?16:25);m.x+=dx/d*speed*dt;m.z+=dz/d*speed*dt;if(d<14){player.hp-= (m.kind===2?13:7)*dt;document.getElementById('damage').classList.add('flash');setTimeout(()=>document.getElementById('damage').classList.remove('flash'),80)}}}updateHUD();if(player.hp<=0){playing=false;document.body.classList.remove('playing');document.getElementById('gameOver').classList.remove('hidden')}if(!won&&player.kills>=12){won=true;toast('A FLORESTA FOI PURIFICADA');document.getElementById('questTitle').textContent='Maldição quebrada';document.getElementById('questText').innerHTML='<b>A floresta respira novamente</b>'}}
function render(){ctx.clearRect(0,0,W,H);drawGround();let list=[];for(const t of trees)list.push({type:'tree',o:t});for(const r of rocks)list.push({type:'rock',o:r});for(const m of monsters)if(!m.dead)list.push({type:'monster',o:m});list.sort((a,b)=>Math.hypot(b.o.x-player.x,b.o.z-player.z)-Math.hypot(a.o.x-player.x,a.o.z-player.z));for(const item of list){if(item.type==='tree')drawTree(item.o);if(item.type==='rock')drawRock(item.o);if(item.type==='monster')drawMonster(item.o)}drawParticles();ctx.save();ctx.translate(W/2,H*.57);ctx.rotate(-player.a*.02);ctx.globalAlpha=.25;ctx.fillStyle='#1b2b1d';ctx.beginPath();ctx.ellipse(0,15,35+Math.sin(player.walk)*3,10,0,0,7);ctx.fill();ctx.restore();}
function loop(now){let dt=Math.min(.033,(now-last)/1000||0);last=now;update(dt);render();requestAnimationFrame(loop)}requestAnimationFrame(loop);
function start(){player.hp=100;player.stamina=100;player.kills=0;player.wood=0;player.x=0;player.z=0;player.a=0;won=false;spawnMonsters();updateHUD();document.getElementById('start').classList.add('hidden');document.getElementById('gameOver').classList.add('hidden');document.body.classList.add('playing');playing=true;toast('EXPLORE. CAÇE. SOBREVIVA.')}
document.getElementById('play').onclick=start;document.getElementById('retry').onclick=start;

